input.command:
cd /tmp && perl -e '
my @cases = (
 ["tab",   "http://a.com:\t80"],
 ["nl",    "http://a.com:\n80"],
 ["vt",    "http://a.com:\x0b80"],
 ["ff",    "http://a.com:\x0c80"],
 ["cr",    "http://a.com:\r80"],
 ["nul-after", "http://a.com:80\x0090"],
 ["nul-before","http://a.com:\x0080"],
 ["sp-mid","http://a.com:8\t0"],
 ["arabic","http://a.com:\x{d9}\x{a8}\x{d9}\xa0"],
 ["longzeros","http://a.com:0000000000000000000000080"],
 ["allzeros","http://a.com:00000000000000000000000000"],
 ["hi-byte","http://a.com:\xff80"],
);
for my $c (@cases) {
  printf("=== [%s] raw=%s\n", $c->[0], unpack("H*",$c->[1]));
  my $pid = fork();
  if ($pid==0) { exec("/workspace/dataset/test5_executable", $c->[1]); exit 127; }
  waitpid($pid,0);
  printf("exit=%d\n", $?>>8);
}
' 2>&1 | head -100

cd /tmp && bad=0; for p in 1 2 7 63 64 127 128 255 256 999 1000 1023 1024 4095 8191 16383 32767 32768 49151 65533 65534 65535; do out=$(/workspace/dataset/test5_executable "http://a.com:$p" | sed -n 3p); [ "$out" = "$p" ] || { echo "MISMATCH $p -> $out"; bad=1; }; done; echo "identity_sample_ok=$((1-bad))"; echo "--- crash hunt ---"; perl -e '
for my $b (0..255) {
  next if $b==0;
  my $u = "http://a.com:" . chr($b) . "80";
  my $pid=fork(); if($pid==0){ open(STDOUT,">/tmp/oo"); open(STDERR,">/tmp/ee"); exec("/workspace/dataset/test5_executable",$u); exit 127;} waitpid($pid,0);
  my $ec=$?>>8; my $sig=$?&127;
  open(F,"/tmp/oo"); my @l=<F>; close F; chomp @l;
  open(G,"/tmp/ee"); my $e=do{local $/;<G>}; close G;
  printf("byte %3d (%s) port=%s exit=%d sig=%d err=%s\n",$b, ($b>=33&&$b<=126)?chr($b):".", $l[2], $ec,$sig,($e ne "")?$e:"-") if ($l[2] ne "-1" || $ec!=0 || $sig!=0 || $e ne "");
}
print "crash_hunt_done\n";'
